import pandas as pd
import numpy as np


def _dedupe_last(df: pd.DataFrame) -> pd.DataFrame:
    # Keep the last occurrence for each (region, sku) key, deterministic tie-break
    # based on original row order (idempotent: re-running on same data gives
    # the same result).
    df = df.copy()
    df["_rn"] = range(len(df))
    df = df.sort_values("_rn")
    df = df.drop_duplicates(subset=["region", "sku"], keep="last")
    df = df.drop(columns=["_rn"]).reset_index(drop=True)
    return df


def _num_equal(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return True
    if a_null or b_null:
        return False
    return a == b


def _label_equal(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return True
    if a_null or b_null:
        return False
    return a.rstrip() == b.rstrip()


def run(inputs: dict) -> dict:
    prev = inputs["snap_prev"].copy()
    curr = inputs["snap_curr"].copy()

    # Ensure key columns are string-typed for safe merging
    for df in (prev, curr):
        df["region"] = df["region"].astype(str)
        df["sku"] = df["sku"].astype(str)

    prev = _dedupe_last(prev)
    curr = _dedupe_last(curr)

    merged = prev.merge(
        curr,
        on=["region", "sku"],
        how="outer",
        suffixes=("_prev", "_curr"),
        indicator=True,
    )

    rows = []
    for _, r in merged.iterrows():
        region = r["region"]
        sku = r["sku"]
        indicator = r["_merge"]

        if indicator == "left_only":
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "D",
                "changed_cols": None,
            })
        elif indicator == "right_only":
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "I",
                "changed_cols": None,
            })
        else:
            diffs = []

            price_eq = _num_equal(r["price_prev"], r["price_curr"])
            if not price_eq:
                diffs.append("price")

            stock_eq = _num_equal(r["stock_prev"], r["stock_curr"])
            if not stock_eq:
                diffs.append("stock")

            label_eq = _label_equal(r["label_prev"], r["label_curr"])
            if not label_eq:
                diffs.append("label")

            if diffs:
                rows.append({
                    "region": region,
                    "sku": sku,
                    "change_type": "U",
                    "changed_cols": ",".join(diffs),
                })
            # else: no row, identical

    if rows:
        out = pd.DataFrame(rows, columns=["region", "sku", "change_type", "changed_cols"])
    else:
        out = pd.DataFrame(columns=["region", "sku", "change_type", "changed_cols"])

    return {"change_log": out}
